{% doc %}
  Fulldev UI typography styles. Use native markup with its data-slot parts.
{% enddoc %}

{{ 'ui-typography.css' | asset_url | stylesheet_tag }}

h1,
h2,
h3,
h4 {
  font-family: var(--font-heading);
  font-weight: var(--heading-weight);
  letter-spacing: var(--tracking-tight);
  scroll-margin-top: 80px;
}
h1 {
  font-size: 2.25rem;
  line-height: 2.5rem;
  text-wrap: balance;
}
h2 {
  font-size: 1.875rem;
  line-height: 2.25rem;
}
h3 {
  font-size: 1.5rem;
  line-height: 2rem;
}
h4 {
  font-size: 1.25rem;
  line-height: 1.75rem;
}
[data-size='sm']:is(h1) {
  font-size: 1.875rem;
  line-height: 2.25rem;
}
[data-size='sm']:is(h2) {
  font-size: 1.5rem;
  line-height: 2rem;
}
[data-size='sm']:is(h3) {
  font-size: 1.25rem;
  line-height: 1.75rem;
}
[data-size='sm']:is(h4) {
  font-size: 1.125rem;
  line-height: 1.75rem;
}
[data-size='lg']:is(h1) {
  font-size: 3rem;
  line-height: 1;
}
.muted {
  color: var(--muted-foreground);
}
.link {
  font-weight: 500;
  text-decoration: underline;
}
.link:hover {
  text-decoration-thickness: 2px;
}

/* Rich text from the editor or Shopify content: Fulldev UI's typography, shadcn/ui's typeset.
   Text is 18px below 768px and 16px from there (sm 14px, lg 18px), headings scale in em, and the
   flow sets the space between blocks. Theme tokens set the colors and fonts, images and videos
   keep square corners, and a wide table scrolls. [data-not-typeset] keeps a part out.
   The typeset class gives merchant rich text inside another part, such as a section or card
   description, the same flow, headings, lists and links at that part's size, leading and color. */
:is([data-slot='typography'], .typeset) {
  --typeset-font-heading: var(--font-heading);
  --typeset-font-mono: var(--font-mono);
  --typeset-flow: 1.25em;
  --typeset-heading: currentcolor;
  --typeset-muted: currentcolor;
  --typeset-rule: var(--border);

  overflow-wrap: break-word;
}
[data-slot='typography'] {
  --typeset-font-body: inherit;
  --typeset-size: 1rem;
  --typeset-leading: 1.75;
  --typeset-heading: var(--foreground);
  --typeset-muted: var(--muted-foreground);

  font-family: var(--typeset-font-body);
  font-size: calc(var(--typeset-size) * 1.125);
  line-height: var(--typeset-leading);
  color: var(--foreground);
}
@media (min-width: 768px), print {
  [data-slot='typography'] {
    font-size: var(--typeset-size);
  }
}
[data-slot='typography'][data-size='sm'] {
  --typeset-size: 0.875rem;
  --typeset-leading: 1.7;
  --typeset-flow: 1.125em;
}
[data-slot='typography'][data-size='lg'] {
  --typeset-size: 1.125rem;
  --typeset-leading: 1.8;
  --typeset-flow: 1.5em;
}
[data-slot='typography'][data-variant='muted'] {
  color: var(--muted-foreground);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(p) {
  margin-block: var(--typeset-flow) 0;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h1),
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h2),
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h3),
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h4),
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h5),
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h6) {
  color: var(--typeset-heading);
  font-family: var(--typeset-font-heading);
  font-weight: var(--heading-weight);
  letter-spacing: var(--tracking-normal);
  margin-block-end: 0;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h1) {
  font-size: 1.75em;
  line-height: 1.3;
  margin-block-start: var(--typeset-flow);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h2) {
  font-size: 1.25em;
  line-height: 1.4;
  margin-block-start: calc(var(--typeset-flow) * 1.4);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h3) {
  font-size: 1.125em;
  line-height: 1.45;
  margin-block-start: var(--typeset-flow);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h4) {
  font-size: 1em;
  line-height: 1.5;
  margin-block-start: var(--typeset-flow);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h5) {
  font-size: 0.875em;
  line-height: 1.5;
  font-weight: 500;
  color: var(--typeset-muted);
  margin-block-start: calc(var(--typeset-flow) / 0.875);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h6) {
  font-size: 0.8125em;
  line-height: 1.5;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--typeset-muted);
  margin-block-start: calc(var(--typeset-flow) / 0.8125);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where([id]) {
  scroll-margin-block-start: var(--typeset-flow);
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(h1 + *, h2 + *, h3 + *, h4 + *, h5 + *, h6 + *) {
  margin-block-start: 1em;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(:is(h1, h2, h3, h4) :is(code)) {
  font-size: 0.9em;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(a) {
  color: inherit;
  font-weight: 500;
  text-decoration-line: underline;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(a:hover) {
  text-decoration-thickness: 2px;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(:is(h1, h2, h3, h4, h5, h6) :is(a)) {
  font-weight: inherit;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(strong, b) {
  font-weight: 600;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(mark) {
  padding: 0.05em 0.15em;
  border-radius: 0.2em;
  background-color: color-mix(in oklab, var(--primary) 15%, transparent);
  color: inherit;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(abbr[title]) {
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-underline-offset: 0.2em;
  cursor: help;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(del, s) {
  color: var(--typeset-muted);
  text-decoration-line: line-through;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(sup, sub) {
  position: relative;
  font-size: 0.75em;
  line-height: 0;
  vertical-align: baseline;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(sup) {
  top: -0.5em;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(sub) {
  bottom: -0.25em;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(sup a) {
  text-decoration-line: none;
  font-weight: 500;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ul) {
  list-style-type: disc;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ol) {
  list-style-type: decimal;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ul ul) {
  list-style-type: circle;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ul ul ul) {
  list-style-type: square;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ol[type='a' i]) {
  list-style-type: lower-alpha;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ol[type='i' i]) {
  list-style-type: lower-roman;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ol[type='A' s]) {
  list-style-type: upper-alpha;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ol[type='I' s]) {
  list-style-type: upper-roman;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ul, ol) {
  margin-block: var(--typeset-flow) 0;
  padding-inline-start: 1.5em;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(li) {
  margin-block-start: 0.5em;
  padding-inline-start: 0.4em;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(li > p, li > ul, li > ol) {
  margin-block-start: 0.5em;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ul > li)::marker,
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(ol > li)::marker {
  color: var(--typeset-muted);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(details) {
  margin-block: var(--typeset-flow) 0;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(summary) {
  cursor: pointer;
  font-weight: 500;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(summary)::marker {
  color: var(--typeset-muted);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(kbd) {
  padding: 0.0625em 0.35em;
  border: 1px solid var(--typeset-rule);
  border-block-end-width: 2px;
  border-radius: min(calc(var(--radius) * 0.6), 0.35em);
  font-family: inherit;
  font-size: 0.85em;
  font-weight: 500;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(dl) {
  margin-block: var(--typeset-flow) 0;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(dt) {
  margin-block-start: 1em;
  font-weight: 500;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(dt + dt) {
  margin-block-start: 0.25em;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(dd) {
  margin-block-start: 0.25em;
  margin-inline-start: 0;
  padding-inline-start: 1em;
  color: var(--typeset-muted);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(:not(pre) > code) {
  padding: 0.125em 0.3em;
  border-radius: min(calc(var(--radius) * 0.6), 0.35em);
  background-color: var(--muted);
  font-family: var(--typeset-font-mono);
  font-size: 0.85em;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(pre) {
  margin-block: calc(var(--typeset-flow) / 0.875) 0;
  overflow-x: auto;
  padding: 0.75em 1em;
  border-radius: var(--radius);
  background-color: var(--muted);
  font-family: var(--typeset-font-mono);
  font-size: 0.875em;
  line-height: 1.5;
  tab-size: 2;
  direction: ltr;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(pre code) {
  padding: 0;
  border-radius: 0;
  background-color: transparent;
  font-family: inherit;
  font-size: inherit;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(blockquote) {
  margin-block: var(--typeset-flow) 0;
  margin-inline: 0;
  padding-inline-start: 1em;
  border-inline-start: 2px solid var(--typeset-rule);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(hr) {
  margin-block: calc(var(--typeset-flow) * 2.4) 0;
  border: 0;
  border-block-start: 1px solid var(--typeset-rule);
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(hr + h1, hr + h2, hr + h3, hr + h4) {
  margin-block-start: var(--typeset-flow);
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(img, video) {
  max-width: 100%;
  height: auto;
  margin-block: var(--typeset-flow) 0;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(iframe) {
  max-width: 100%;
  margin-block: var(--typeset-flow) 0;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(p img) {
  margin-block-start: 0;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(figure) {
  margin-block: var(--typeset-flow) 0;
  margin-inline: 0;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(figcaption, caption) {
  margin-block-start: calc(0.75em / 0.875);
  color: var(--typeset-muted);
  font-size: 0.875em;
  text-align: center;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(caption) {
  caption-side: bottom;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(table) {
  display: block;
  width: max-content;
  max-width: 100%;
  margin-block: var(--typeset-flow) 0;
  overflow-x: auto;
  border-block-end: 1px solid var(--typeset-rule);
  border-collapse: separate;
  border-spacing: 0;
  font-size: 1em;
  line-height: 1.5;
  font-variant-numeric: tabular-nums;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(thead th) {
  padding: 0.65em 1em;
  font-weight: 500;
  text-align: start;
  white-space: nowrap;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(:is(tbody, tfoot) :is(td, th)) {
  padding: 0.75em 1em;
  border-block-start: 1px solid var(--typeset-rule);
  text-align: start;
  vertical-align: top;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(tbody th, tfoot th) {
  font-weight: 500;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(th:first-child, td:first-child) {
  padding-inline-start: 0;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(th[align='center'], td[align='center']) {
  text-align: center;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(th[align='right'], td[align='right']) {
  text-align: end;
}
:is([data-slot='typography'], .typeset)
  :not(:where([data-not-typeset], [data-not-typeset] *)):where(li > blockquote, li > table, li > figure) {
  margin-block-start: 0.5em;
}
:is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(li > pre) {
  margin-block-start: calc(0.5em / 0.875);
}
@media print {
  :is([data-slot='typography'], .typeset)
    :not(:where([data-not-typeset], [data-not-typeset] *)):where(pre, table, blockquote, figure) {
    break-inside: avoid;
  }
  :is([data-slot='typography'], .typeset) :not(:where([data-not-typeset], [data-not-typeset] *)):where(h1, h2, h3, h4) {
    break-after: avoid;
  }
}
@media (forced-colors: active) {
  :is([data-slot='typography'], .typeset)
    :not(:where([data-not-typeset], [data-not-typeset] *)):where(:not(pre) > code) {
    border: 1px solid;
  }
}
:is([data-slot='typography'], .typeset) > :where(:first-child):not(:where([data-not-typeset], [data-not-typeset] *)),
:is([data-slot='typography'], .typeset)
  > :where(:first-child)
  > :where(:first-child):not(:where([data-not-typeset], [data-not-typeset] *)),
:is([data-slot='typography'], .typeset)
  :where(
    li > :first-child,
    blockquote > :first-child,
    td > :first-child,
    th > :first-child,
    dd > :first-child,
    figure > :first-child,
    figure > picture > img
  ):not(:where([data-not-typeset], [data-not-typeset] *)) {
  margin-block-start: 0;
}

/* Typography parts, as Fulldev UI's typography components: the same roles outside rich text,
   each with the sm and lg sizes. Large, small and muted are shadcn/ui's typography roles. */
[data-slot='typography-h1'],
[data-slot='typography-h2'],
[data-slot='typography-h3'],
[data-slot='typography-h4'] {
  font-family: var(--font-heading);
  font-weight: var(--heading-weight);
  letter-spacing: var(--tracking-tight);
  scroll-margin-top: 80px;
}
[data-slot='typography-h1'] {
  text-wrap: balance;
  font-size: 2.25rem;
  line-height: 2.5rem;
}
[data-slot='typography-h1'][data-size='sm'] {
  font-size: 1.875rem;
  line-height: 2.25rem;
}
[data-slot='typography-h1'][data-size='lg'] {
  font-size: 3rem;
  line-height: 1;
}
[data-slot='typography-h2'] {
  font-size: 1.875rem;
  line-height: 2.25rem;
}
[data-slot='typography-h2'][data-size='sm'] {
  font-size: 1.5rem;
  line-height: 2rem;
}
[data-slot='typography-h2'][data-size='lg'] {
  font-size: 2.25rem;
  line-height: 2.5rem;
}
[data-slot='typography-h3'] {
  font-size: 1.5rem;
  line-height: 2rem;
}
[data-slot='typography-h3'][data-size='sm'] {
  font-size: 1.25rem;
  line-height: 1.75rem;
}
[data-slot='typography-h3'][data-size='lg'] {
  font-size: 1.875rem;
  line-height: 2.25rem;
}
[data-slot='typography-h4'] {
  font-size: 1.25rem;
  line-height: 1.75rem;
}
[data-slot='typography-h4'][data-size='sm'] {
  font-size: 1.125rem;
  line-height: 1.75rem;
}
[data-slot='typography-h4'][data-size='lg'] {
  font-size: 1.5rem;
  line-height: 2rem;
}
[data-slot='typography-p'],
[data-slot='typography-blockquote'],
[data-slot='typography-list'] {
  font-size: 1rem;
  line-height: 1.75rem;
}
[data-slot='typography-p']:not(:first-child) {
  margin-top: 1.5rem;
}
[data-slot='typography-lead'] {
  font-size: 1.125rem;
  line-height: 1.75rem;
  color: var(--muted-foreground);
}
[data-slot='typography-lead'][data-size='sm'] {
  font-size: 1rem;
  line-height: 1.5rem;
}
[data-slot='typography-lead'][data-size='lg'] {
  font-size: 1.25rem;
  line-height: 1.75rem;
}
[data-slot='typography-large'] {
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.75rem;
}
[data-slot='typography-small'] {
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;
}
[data-slot='typography-muted'] {
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: var(--muted-foreground);
}
[data-slot='typography-blockquote'] {
  margin-top: 1.5rem;
  padding-inline-start: 1.5rem;
  border-inline-start: 2px solid var(--border);
  font-style: italic;
}
[data-slot='typography-list'] {
  margin-block: 1.5rem;
  padding-inline-start: 1.5rem;
}
[data-slot='typography-list'] > li + li {
  margin-top: 0.5rem;
}
[data-slot='typography-p'][data-size='sm'] {
  font-size: 0.875rem;
  line-height: 1.5rem;
}
[data-slot='typography-p'][data-size='lg'] {
  font-size: 1.125rem;
  line-height: 1.875rem;
}
[data-slot='typography-blockquote'][data-size='sm'] {
  font-size: 0.875rem;
  line-height: 1.5rem;
}
[data-slot='typography-blockquote'][data-size='lg'] {
  font-size: 1.125rem;
  line-height: 1.875rem;
}
[data-slot='typography-list'][data-size='sm'] {
  font-size: 0.875rem;
  line-height: 1.5rem;
}
[data-slot='typography-list'][data-size='lg'] {
  font-size: 1.125rem;
  line-height: 1.875rem;
}
[data-slot='typography-inline-code'] {
  padding: 0.2rem 0.3rem;
  border-radius: var(--radius-sm);
  background: var(--muted);
  font-family: var(--font-mono);
  font-size: 0.875rem;
  font-weight: 600;
}
[data-slot='typography-inline-code'][data-size='sm'] {
  font-size: 0.75rem;
}
[data-slot='typography-inline-code'][data-size='lg'] {
  font-size: 1rem;
}
[data-slot='typography-a'] {
  color: var(--primary);
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.5rem;
  text-decoration: underline;
  text-underline-offset: 4px;
}
[data-slot='typography-a'][data-size='sm'] {
  font-size: 0.875rem;
  line-height: 1.25rem;
}
[data-slot='typography-a'][data-size='lg'] {
  font-size: 1.125rem;
  line-height: 1.75rem;
}
[data-slot='typography-a']:hover {
  text-decoration-thickness: 2px;
}

/* A table in running text, as Fulldev UI's typography table: framed, with striped rows. */
[data-slot='typography-table-container'] {
  width: 100%;
  margin-block: 1.5rem;
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
}
[data-slot='typography-table'] {
  width: 100%;
  border-collapse: collapse;
  font-size: 1rem;
  line-height: 1.5rem;
}
[data-slot='typography-table'][data-size='sm'] {
  font-size: 0.875rem;
  line-height: 1.25rem;
}
[data-slot='typography-table'][data-size='lg'] {
  font-size: 1.125rem;
  line-height: 1.75rem;
}
[data-slot='typography-table-row']:nth-child(even) {
  background: var(--muted);
}
[data-slot='typography-table-head'],
[data-slot='typography-table-cell'] {
  padding: 0.75rem 1rem;
  text-align: start;
}
[data-slot='typography-table-head'] {
  border-bottom: 1px solid var(--border);
  font-weight: 600;
}
[data-slot='typography-table-cell'] {
  border-top: 1px solid var(--border);
}
:is([data-slot='typography-table-head'], [data-slot='typography-table-cell'])[align='left'] {
  text-align: left;
}
:is([data-slot='typography-table-head'], [data-slot='typography-table-cell'])[align='center'] {
  text-align: center;
}
:is([data-slot='typography-table-head'], [data-slot='typography-table-cell'])[align='right'] {
  text-align: right;
}

.check-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 0.875rem;
}
.check-list > li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}
.check-list .icon {
  width: 16px;
  height: 16px;
  margin-top: 2px;
  color: var(--primary);
}
